216	
217	            return savedPayment;
218	        } catch (PaymentException e) {
219	            throw e; // 이미 PaymentException이면 그대로 전파
220	        } catch (Exception e) {
221	            log.error("카드 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
