148	public enum SaleStatus {
149	    PENDING_SHIPMENT,    // 판매자 발송 대기
150	    IN_TRANSIT,          // 배송 중
151	    IN_INSPECTION,       // 검수 중
152	    FAILED_INSPECTION,   // 검수 불합격
153	    IN_STORAGE,          // 창고 보관 중
154	    ON_AUCTION,          // 판매 입찰 중
155	    SELLING,             // 판매중 (등록된 상태)
156	    SOLD,                // 판매 완료
157	    AUCTION_EXPIRED;     // 입찰 기한 만료
158	
159	    // 상태 전환 규칙
160	    public boolean canTransitionTo(SaleStatus newStatus) {
161	        return switch (this) {
162	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
163	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
164	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
165	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
166	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
167	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
168	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
169	        };
170	    }
